def style(b, e):
    if b in DEEP: return "abyss"
    if e == "comic": return "storybook"
    return "ink" if e in ("challenge",) else "nocturne"

TONE = {"signal": "mysterious", "discovery": "scientific", "encounter": "mysterious", "evidence": "mysterious", "challenge": "tense",
        "suspense": "eerie", "comic": "comic", "finale": "heroic"}
out = []
for i, (b, e, sfx, p) in enumerate(S):
    out.append({"id": f"{b.lower() if b != 'openSea' else 'opensea'}-{sfx}", "biome": b, "event": e, "tone": TONE[e],
                "mystery": 2 if e in ("signal", "suspense", "evidence") else 1, "style": style(b, e), "seed": 9300 + i, "prompt": p})
json.dump(out, open("scripts/comfy/plates-batch3.json", "w", encoding="utf-8"), indent=0)
print(len(out))
